// Concept / programmatic 3D reconstruction attribution: @r_peredelkino · RP-CONCEPT-2026-10-07
function dateInMoscow(){const value=new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',weekday:'long',day:'numeric',month:'long'}).format(new Date());return value.charAt(0).toUpperCase()+value.slice(1)}
function weatherCard(){const w=window.residentWeather;if(!w)return (window.weatherUnavailable?'Погода недоступна':'Погода…')+'<small>Переделкино</small>';const symbols={clear:'☀',clouds:'☁',rain:'☂',snow:'❄',fog:'≋'};return symbols[w.kind]+' '+Math.round(w.temperature)+'°<small>Переделкино · Open-Meteo</small>'}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',key:'M15 7a5 5 0 1 1-3 9L5 23H1v-4l7-7a5 5 0 0 1 7-5M16 10h.01',cam:'M3 6h12v12H3z M15 10l6-3v10l-6-3',chat:'M21 11a9 9 0 0 1-9 9H4l-3 2 2-6a9 9 0 1 1 18-5M7 10h10M7 14h6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',light:'M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0l-1 2H9z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',blinds:'M3 4h18M5 4v16M19 4v16M5 8h14M5 12h14M5 16h14',drop:'M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13',game:'M7 7h10l4 10c1 4-3 4-5 0H8c-2 4-6 4-5 0zM6 11h5M8.5 8.5v5M16 11h.01M18 14h.01',send:'m3 3 18 9-18 9 4-9zM7 12h14',back:'m14 5-7 7 7 7',doc:'M6 2h9l4 4v16H6zM9 10h7M9 14h7M9 18h4',car:'M5 6h14l3 8v5H2v-5zM2 14h20M6 17h.01M18 17h.01M5 19v3M19 19v3',plus:'M12 4v16M4 12h16',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 22v-3a8 8 0 0 1 16 0v3'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('rodina-concept-v1'))}catch{}state={temp:23,lights:true,blinds:false,water:true,security:true,scene:'Дома',bookings:[],messages:{},passes:[],requests:[],paid:false,...state};
let page='home',room=null,filter='Все',chatFilter='Все',activeCam=0;
const save=()=>{try{localStorage.setItem('rodina-concept-v1',JSON.stringify(state))}catch{toast('Хранилище недоступно: изменения до закрытия страницы')}};
const cameras=[{name:'Центральный двор',zone:'Двор',img:'garden',id:'01'},{name:'Панорама комплекса',zone:'Крыша',img:'hero',id:'02'},{name:'Главное лобби',zone:'Лобби',img:'lobby',id:'03'},{name:'Подземный паркинг',zone:'Паркинг',img:'parking',id:'04'},{name:'Внешний периметр',zone:'Периметр',img:'hero',id:'05'},{name:'Киберарена',zone:'Двор',img:'arena',id:'06'}];
const rooms=[{id:'concierge',name:'Ваш консьерж',sub:'Анна · поможем с любым вопросом',icon:'spark',preview:'Добрый день! Чем могу помочь?',time:'12:40',count:1},{id:'neighbors',name:'Соседи · Корпус 3',sub:'Общий чат · демо-участники',icon:'home',preview:'Мария: Кто сегодня на прогулку?',time:'12:32',count:3},{id:'gaming',name:'RODINA PLAY',sub:'Киберсообщество · демо-участники',icon:'game',preview:'Алексей: Собираем команду на вечер',time:'12:15',count:2},{id:'support',name:'Управляющая компания',sub:'Служба заботы · демо-диалог',icon:'shield',preview:'Все обращения в одном месте',time:'Вчера',count:0}];
const defaults={concierge:[{text:'Евгений, добрый день! Я Анна, ваш консьерж. Помогу с доставкой, гостевым доступом или бронированием лобби.',author:'Анна · консьерж'}],neighbors:[{text:'Всем привет! Кто сегодня на прогулку по лесопарку? Встречаемся у центрального лобби в 19:00.',author:'Мария · соседка'},{text:'Мы с вами! Возьмём кофе по дороге ☕',author:'Дмитрий · сосед'}],gaming:[{text:'Собираем команду на вечер в RODINA PLAY. Начало в 20:00, осталось два места. Кто с нами?',author:'Алексей · комьюнити'}],support:[{text:'Здравствуйте! Опишите вопрос — покажем, как будет выглядеть общение со службой заботы.',author:'Служба заботы'}]};
function navigate(p){if(!['home','smart','cameras','chats','services'].includes(p))throw Error('Неизвестный экран');page=p;room=null;render();window.scrollTo({top:0,behavior:'instant'});}
function head(k,t,s=''){return `<div class="page-head"><span class="eyebrow">${k}</span><h2>${t}</h2>${s?`<p class="section-subtitle">${s}</p>`:''}</div>`}
function row(i,t,s,action){return `<button class="row" onclick="${action}"><span class="row-icon">${icon(i)}</span><span class="body"><b>${t}</b><small>${s}</small></span><span class="chev">›</span></button>`}
function render(){document.querySelector('#nav').innerHTML=[['home','home','Главная'],['smart','spark','Мой дом'],['cameras','cam','Камеры'],['chats','chat','Чаты'],['services','grid','Сервисы']].map(([p,i,t])=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="navigate('${p}')">${icon(i)}${t}</button>`).join('');document.querySelector('#main').innerHTML=({home:home,smart:smart,cameras:cameraPage,chats:chatPage,services:services}[page])();}
function home(){return `<div class="greeting"><div><p>${dateInMoscow()}</p><h2>Вы дома, Евгений.</h2></div><div class="weather">${weatherCard()}</div></div><section class="hero"><img src="assets/hero.webp" alt="Архитектура Родина Переделкино"><div class="hero-top"><span class="pill">КОРПУС 3 · КВ. 128</span><span class="pill">Ваше пространство</span></div><div class="hero-bottom"><small>ГОРОД, КОТОРЫЙ ЧУВСТВУЕТ ВАС</small><h2>Всё начинается дома.</h2><div class="hero-status"><span class="dot"></span> ${state.security?'Дом под защитой':'Режим без охраны'}<span>Демо-сценарий</span></div></div></section><div class="quick">${[['key','Открыть','access'],['user','Гостевой вход','guest'],['spark','Консьерж','concierge'],['car','Паркинг','parking']].map(([i,t,a])=>`<button onclick="${a==='concierge'?"openChat('concierge')":`openSheet('${a}')`}"><span class="iconbox">${icon(i)}</span>${t}</button>`).join('')}</div><div class="section-title"><h3>Квартира под контролем</h3><button onclick="navigate('smart')">Управлять</button></div><section class="home-card"><div class="home-card-head"><h3>Мой дом</h3><span>128 · 18 этаж</span></div><div class="home-metrics"><div class="metric"><b>${state.temp}°</b><small>Температура</small></div><div class="metric"><b>42<span style="font-size:16px">%</span></b><small>Влажность</small></div><div class="metric"><b>Отлично</b><small>Качество воздуха</small></div></div>${scenes()}</section><div class="section-title"><h3>Жизнь кластера</h3><button onclick="navigate('services')">Все события</button></div><button class="event" onclick="openSheet('arena')"><img src="assets/arena.webp" alt="Киберспортивное пространство"><div class="event-content"><small>RODINA PLAY / СЕГОДНЯ</small><h3>Вечер для<br>своей команды.</h3><p>20:00 · Киберарена · Демо-событие</p></div></button><p class="footer-note">Независимый концепт. Показатели и действия демонстрационные. Визуализации: <a href="https://rodina-peredelkino.ru/" target="_blank" rel="noopener">Группа Родина</a>.</p>`}
function scenes(){return `<div class="scenes">${['Дома','Я ушёл','Ночь'].map((s,i)=>`<button class="${state.scene===s?'active':''}" onclick="setScene(${i})">${['⌂','↗','☾'][i]} ${s}</button>`).join('')}</div>`}
function setScene(i){const s=['Дома','Я ушёл','Ночь'][i];if(!s)return;state.scene=s;state.lights=i===0;state.security=i!==0;state.blinds=i!==0;save();render();toast('Сценарий «'+s+'» включён · демо')}
function smart(){return head('SMART LIVING','Мой дом','Корпус 3 · Квартира 128')+scenes()+`<div class="section-title"><h3>Идеальный климат</h3><span style="color:var(--lime);font-size:12px">Демо · Авто</span></div><section class="thermostat"><p style="color:var(--muted);font-size:13px">ГОСТИНАЯ</p><div class="thermo-ring"><div><strong>${state.temp}°</strong><small>Целевая температура</small></div></div><div class="temperature-controls"><button class="round" aria-label="Уменьшить температуру" onclick="temperature(-1)" ${state.temp<=16?'disabled':''}>−</button><span>Поддержание климата</span><button class="round" aria-label="Увеличить температуру" onclick="temperature(1)" ${state.temp>=30?'disabled':''}>+</button></div></section><div class="device-grid">${[['lights','light','Освещение',state.lights?'Свет включён':'Свет выключен'],['blinds','blinds','Шторы',state.blinds?'Закрыты':'Открыты'],['water','drop','Водоснабжение',state.water?'Кран открыт':'Кран закрыт'],['security','shield','Охрана',state.security?'Под защитой':'Отключена']].map(([k,i,t,s])=>`<button class="device ${state[k]?'on':''}" role="switch" aria-checked="${state[k]}" aria-label="${t}" onclick="toggle('${k}')"><span class="device-top">${icon(i)}<span class="switch"></span></span><h3>${t}</h3><small>${s}</small></button>`).join('')}</div><div class="notice">Настройки сохраняются на этом устройстве. Оборудование квартиры не подключено.</div>`}
function temperature(d){state.temp=Math.max(16,Math.min(30,state.temp+d));save();render()}
function toggle(k){state[k]=!state[k];state.scene='';save();render();toast('Состояние устройства изменено · демо')}
function cameraPage(){return head('В ПОЛЕ ЗРЕНИЯ','Камеры','Ваш комплекс. С любого ракурса.')+`<div class="chips">${['Все','Двор','Крыша','Лобби','Паркинг','Периметр'].map(f=>`<button class="${filter===f?'active':''}" onclick="filter='${f}';render()">${f}</button>`).join('')}</div><div class="camera-grid">${cameras.map((c,i)=>filter==='Все'||filter===c.zone?`<button class="camera" onclick="showCamera(${i})"><div class="camera-image"><img src="assets/${c.img}.webp" alt="${c.name}"><span class="cam-label">ДЕМО · CAM ${c.id}</span></div><div class="camera-info"><h3>${c.name}</h3><small>${c.zone} · Визуализация</small></div></button>`:'').join('')}</div><div class="notice"><b>Режим демонстрации.</b> Здесь рендеры комплекса, а не трансляции с камер. Ракурсы условные. Просмотр архива показывает только работу интерфейса.</div>`}
function showCamera(i){activeCam=i;openSheet('camera')}
function chatPage(){if(room)return chatThread();return head('ВАШЕ СООБЩЕСТВО','Всегда на связи','Соседи, команда и забота о вашем доме.')+`<div class="chips">${['Все','Соседи','Сервисы'].map(f=>`<button class="${chatFilter===f?'active':''}" onclick="chatFilter='${f}';render()">${f}</button>`).join('')}</div><div class="list chat-list">${rooms.filter(r=>chatFilter==='Все'||(chatFilter==='Сервисы'?['concierge','support'].includes(r.id):['neighbors','gaming'].includes(r.id))).map(r=>{let m=state.messages[r.id];return `<button class="row" onclick="openChat('${r.id}')"><span class="room-avatar">${icon(r.icon)}</span><span class="body"><b>${r.name}</b><small>${esc(m?.at(-1)?.text||r.preview)}</small></span><span><time>${r.time}</time>${r.count?`<span class="badge">${r.count}</span>`:''}</span></button>`}).join('')}</div><div class="notice">Демо-чаты: сообщения хранятся только на этом устройстве. Ответы автоматические; настоящие соседи и консьерж их не получают.</div>`}
function openChat(id){if(!rooms.some(r=>r.id===id))return;closeSheet();page='chats';room=id;render();window.scrollTo(0,0)}
function chatThread(){let r=rooms.find(r=>r.id===room),messages=state.messages[room]||defaults[room];return `<div class="chat-title"><button onclick="room=null;render()" aria-label="Назад к чатам">${icon('back')}</button><span class="room-avatar">${icon(r.icon)}</span><div><h3>${r.name}</h3><small>${r.sub}</small></div></div><div class="notice">Демонстрационный диалог · автоматические ответы</div><div class="chat-date">Сегодня</div><div class="messages" id="messages">${messages.map(m=>`<div class="message ${m.mine?'mine':''}">${m.author?`<span class="author">${esc(m.author)}</span>`:''}${esc(m.text)}<time>${m.time||'12:40'} ${m.mine?'✓✓':''}</time></div>`).join('')}</div><form class="composer" onsubmit="sendMessage(event)"><input aria-label="Сообщение" id="message-input" placeholder="Написать сообщение…" maxlength="1500" autocomplete="off" required><button class="send" aria-label="Отправить сообщение">${icon('send')}</button></form>`}
function sendMessage(e){e.preventDefault();const input=document.querySelector('#message-input'),text=input.value.trim();if(!text)return;const id=room;if(!state.messages[id])state.messages[id]=[...defaults[id]];const time=new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'});state.messages[id].push({text,mine:true,time});save();render();document.querySelector('#message-input').focus();setTimeout(()=>{let answer=id==='concierge'?'Принято! В реальном приложении я передам запрос консьержу. В демо можно самостоятельно создать гостевой пропуск или забронировать лобби в разделе «Сервисы».':id==='support'?'Спасибо за сообщение. Это автоматический демо-ответ. Для примера регистрации обращения откройте «Сервисы → Заявка в УК».':id==='gaming'?'Отлично! В демо можно забронировать тренировку в разделе «Сервисы → Киберарена». Увидимся в команде!':'Спасибо, что присоединились к разговору! Это пример ответа соседа. Настоящий общий чат появится после подключения сервера.';state.messages[id].push({text:answer,author:id==='concierge'?'Анна · демо':id==='support'?'Служба заботы · демо':'Участник · демо',time});save();if(room===id&&page==='chats')render()},850)}
function services(){return head('БОЛЬШЕ, ЧЕМ ДОМ','Ваши возможности','Всё важное — рядом.')+`<div class="balance"><p>ЖКУ · Октябрь · Демо-счёт</p><div class="amount">${state.paid?'0':'8 450'} <small>₽</small></div><p>${state.paid?'Демонстрационная оплата выполнена':'К оплате до 10 октября'}</p><button class="primary" onclick="openSheet('bill')">${state.paid?'История оплаты':'Посмотреть счёт'}</button></div><div class="list">${row('doc','Счётчики','Передать показания воды и электричества',"openSheet('meters')")}${row('key','Гостевой доступ',state.passes.length?`${state.passes.length} демо-пропусков`:'Пригласить друзей или курьера',"openSheet('guest')")}${row('shield','Заявка в УК',state.requests.length?`${state.requests.length} обращений в демо`:'Дом, инженерия и общие пространства',"openSheet('request')")}${row('spark','Консьерж','Доставка, помощь и особые поручения',"openChat('concierge')")}</div><div class="section-title"><h3>Пространства для вас</h3></div>${[['arena','Киберарена','Тренировки · Командная игра'],['lobby','Лобби и коворкинг','Переговорная · Работа · Встречи']].map(([i,t,s])=>`<button class="booking" style="width:100%;text-align:left" onclick="openSheet('${i}')"><img src="assets/${i}.webp" alt="${t}"><span><h3>${t}</h3><small>${s}</small></span><span style="margin-left:auto">›</span></button>`).join('')}${state.bookings.length?`<div class="section-title"><h3>Мои бронирования</h3></div>${state.bookings.map((b,i)=>`<div class="home-card" style="margin-bottom:10px"><h3>${esc(b.name)}</h3><p class="section-subtitle">${esc(b.date)} · ${esc(b.time)}</p><button class="link-button" onclick="cancelBooking(${i})">Отменить бронь</button></div>`).join('')}`:''}<p class="footer-note">Все сервисы работают в демонстрационном режиме. Платежи не списываются, доступ не выдаётся.</p>`}
function cancelBooking(i){state.bookings.splice(i,1);save();render();toast('Демо-бронирование отменено')}
function closeSheet(){document.querySelector('#sheet').close()}
function openSheet(type){const body=document.querySelector('#sheet-body');let html='';
if(type==='profile')html=`<h2>Евгений</h2><p>Резидент · демо-профиль</p><div class="list" style="margin-top:20px">${row('home','Квартира 128','Корпус 3 · 18 этаж',"openSheet('residence')")}${row('car','Машиноместо 042','Уровень −1',"openSheet('parking')")}</div><div class="notice">Независимый концепт будущего приложения. Не официальный сервис застройщика. Данные вымышлены.</div><a class="secondary" style="display:block;text-align:center;text-decoration:none" href="RODINA-IOS-BRIEF.md" download>Задание для iOS-разработки</a>`;
if(type==='residence')html=`<h2>Мои пространства</h2><p>Родина Переделкино</p><div class="list" style="margin-top:20px">${row('home','Квартира 128','Корпус 3 · 18 этаж · Выбрана',"closeSheet()")}${row('car','Машиноместо 042','Уровень −1',"openSheet('parking')")}</div>`;
if(type==='access')html=`<h2>Добро пожаловать домой</h2><img class="full-image" src="assets/lobby.webp" alt="Лобби"><p>Главный вход · Корпус 3<br>Демонстрация дистанционного открытия двери.</p><button class="primary" onclick="unlock(this)">Открыть дверь · демо</button>`;
if(type==='parking')html=`<h2>Ваш паркинг</h2><img class="full-image" src="assets/parking.webp" alt="Паркинг"><div class="inline-metrics"><div><b>042</b><small>Машиноместо</small></div><div><b>−1</b><small>Уровень</small></div><div><b>Свободен</b><small>Демо-статус въезда</small></div></div><button class="primary" onclick="unlock(this,'Шлагбаум')">Открыть шлагбаум · демо</button>`;
if(type==='guest')html=`<h2>Ждёте гостей?</h2><p>Создайте демонстрационный пропуск. Он не даёт доступ в настоящий комплекс.</p><form onsubmit="createPass(event)"><label class="field">Имя гостя<input name="name" placeholder="Например, Александр" required maxlength="60"></label><label class="field">Куда предоставить доступ<select name="zone"><option>Главное лобби</option><option>Гостевой паркинг</option><option>Вход во двор</option></select></label><label class="field">Срок действия<select name="duration"><option>На 2 часа</option><option>На 24 часа</option></select></label><button class="primary">Создать демо-пропуск</button></form>${state.passes.length?'<div class="notice">Последние пропуска: '+state.passes.slice(-3).map(p=>esc(p.name)+' · '+p.code).join('<br>')+'</div>':''}`;
if(type==='camera'){const c=cameras[activeCam];html=`<h2>${c.name}</h2><div class="camera-view"><img class="full-image" src="assets/${c.img}.webp" alt="Демо-кадр"><span class="cam-label">ДЕМО · CAM ${c.id}</span><span class="camera-clock" id="camera-time">Сегодня · 12:40</span></div><p>Архив · демонстрация навигации</p><input aria-label="Время в архиве" type="range" min="0" max="23" value="12" oninput="document.querySelector('#camera-time').textContent='Сегодня · '+String(this.value).padStart(2,'0')+':00';document.querySelector('#archive-label').textContent='Выбрано '+String(this.value).padStart(2,'0')+':00'"><div class="timeline"><span>00:00</span><span id="archive-label">Выбрано 12:00</span><span>23:00</span></div><div class="notice">Статичный архитектурный рендер. Видеопоток и записи отсутствуют.</div><button class="secondary" onclick="closeSheet();openChat('support')">Связаться со службой заботы</button>`}
if(type==='bill')html=`<h2>Счёт за октябрь</h2><p>Квартира 128 · Демо-начисления</p><div class="amount">${state.paid?'0':'8 450'} <small>₽</small></div><div class="list">${row('home','Содержание дома','4 120 ₽',"void(0)")}${row('drop','Вода и отопление','2 380 ₽',"void(0)")}${row('light','Электроэнергия','1 950 ₽',"void(0)")}</div><p style="margin-top:18px">${state.paid?'Демо-счёт отмечен оплаченным. Реальных списаний нет.':'Платёжные данные не нужны. Кнопка только покажет успешную оплату.'}</p>${state.paid?'':`<button class="primary" onclick="state.paid=true;save();closeSheet();render();toast('Демо-оплата выполнена. Деньги не списаны')">Демо-оплата 8 450 ₽</button>`}`;
if(type==='meters')html=`<h2>Показания счётчиков</h2><p>Последние: холодная вода 124 м³, горячая 86 м³, электричество 2 340 кВт·ч.</p><form onsubmit="submitMeters(event)">${[['cold','Холодная вода, м³',124],['hot','Горячая вода, м³',86],['electric','Электричество, кВт·ч',2340]].map(([n,t,v])=>`<label class="field">${t}<input type="number" name="${n}" min="${state.meters?.[n]||v}" step="0.01" value="${state.meters?.[n]||v}" required></label>`).join('')}<button class="primary">Сохранить показания · демо</button></form>`;
if(type==='request')html=`<h2>Как мы можем помочь?</h2><p>Демо-заявка сохранится на этом устройстве.</p><form onsubmit="submitRequest(event)"><label class="field">Категория<select name="category"><option>Инженерия квартиры</option><option>Общие пространства</option><option>Уборка</option><option>Безопасность</option></select></label><label class="field">Что произошло?<textarea name="text" minlength="10" maxlength="2000" required placeholder="Опишите проблему и место"></textarea></label><button class="primary">Создать демо-заявку</button></form>${state.requests.length?'<div class="notice">Мои обращения<br>'+state.requests.map(r=>'№'+r.id+' · '+esc(r.category)+' · Создано в демо').join('<br>')+'</div>':''}`;
if(type==='arena'||type==='lobby'){let name=type==='arena'?'Киберарена':'Лобби и коворкинг';html=`<h2>${name}</h2><img class="full-image" src="assets/${type}.webp" alt="${name}"><p>${type==='arena'?'Соберите команду. Тренировка, турнир или вечер игры — в своём кластере.':'Место для спокойной работы и важных встреч. Забронируйте переговорную на час.'}</p><form onsubmit="book(event,'${name}')"><label class="field">Дата<input type="date" name="date" value="${new Date().toISOString().slice(0,10)}" min="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Время<select name="time"><option>18:00–19:00</option><option>19:00–20:00</option><option>20:00–21:00</option></select></label><button class="primary">Забронировать · демо</button></form><div class="notice">Расписание и доступность вымышлены. Это демонстрация будущего сервиса.</div>`}
body.innerHTML=html;const d=document.querySelector('#sheet');if(!d.open)d.showModal();d.scrollTop=0;
}
function unlock(b,object='Дверь'){b.disabled=true;b.textContent='Открываем…';setTimeout(()=>{b.textContent=object+' открыт · демо';toast('Имитация: '+object.toLowerCase()+' открыт');setTimeout(()=>{b.disabled=false;b.textContent='Открыть ещё раз · демо'},2200)},700)}
function createPass(e){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;const code=String(Math.floor(100000+Math.random()*900000));state.passes.push({name,code,zone:f.get('zone'),duration:f.get('duration'),created:Date.now()});save();document.querySelector('#sheet-body').innerHTML=`<div class="success-icon">✓</div><h2>Гость приглашён · демо</h2><p>${esc(name)} · ${esc(f.get('zone'))}<br>${esc(f.get('duration'))}</p><div class="pass-code">${code}</div><p>Демонстрационный код. Не работает в реальной системе доступа и никому не отправлен.</p><button class="primary" onclick="closeSheet();render()">Готово</button>`}
function submitMeters(e){e.preventDefault();const f=new FormData(e.target);state.meters=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]));save();closeSheet();toast('Показания сохранены локально · демо')}
function submitRequest(e){e.preventDefault();let f=new FormData(e.target);if(f.get('text').trim().length<10){toast('Опишите проблему: минимум 10 символов');return}state.requests.push({id:1001+state.requests.length,category:f.get('category'),text:f.get('text')});save();closeSheet();render();toast('Демо-заявка №'+state.requests.at(-1).id+' создана')}
function book(e,name){e.preventDefault();let f=new FormData(e.target),date=f.get('date'),time=f.get('time');if(state.bookings.some(b=>b.name===name&&b.date===date&&b.time===time)){toast('У вас уже есть бронь на это время');return}state.bookings.push({name,date,time});save();closeSheet();page='services';render();toast('Бронирование сохранено · демо')}
let toastTimer;function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
document.querySelector('#sheet').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet()}});
if(document.body.dataset.experience!=='genplan')render();
if(document.body.dataset.experience!=='genplan'&&document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_resident_demo',title:'Открыть раздел приложения',description:'Navigate the resident demo without changing device states.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['home','smart','cameras','chats','services']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({page:p})=>{navigate(p);return{page}}})}catch(e){console.warn('WebMCP unavailable')}}
